use super::*;
impl Eclipse {
    pub(in crate::ui) fn server_settings_window(&mut self,ctx:&egui::Context){
        if !self.server_settings{return;}
        crate::settings_layout::set_accent(ctx,self.accent());
        let name=self.server.metadata["name"].as_str().unwrap_or("Server").to_owned();
        let close=crate::settings_layout::shell(ctx,"server-settings",&name,"Server Settings",|ui,size|{
            ui.horizontal_top(|ui|{
                ui.spacing_mut().item_spacing.x=0.;
                egui::Frame::NONE.fill(RAIL).inner_margin(egui::Margin{left:12,right:12,top:6,bottom:12}).show(ui,|ui|{ui.vertical(|ui|{ui.set_width(196.);ui.set_height(size.y-18.);
                    egui::ScrollArea::vertical().id_salt("server-settings-nav").max_height(size.y-18.).show(ui,|ui|{
                        for(category,pages)in preferences::SERVER_CATEGORIES{ui.add_space(14.);ui.label(RichText::new(*category).size(10.5).strong().color(MUTED));ui.add_space(2.);
                            for page in *pages{let selected=self.server_page==*page;if crate::widgets::nav_row(ui,page,selected,if selected{TEXT}else{MUTED}).clicked(){self.server_page=(*page).into();self.load_server_page();}}
                        }
                    });
                });});
                egui::Frame::NONE.inner_margin(egui::Margin{left:30,right:18,top:20,bottom:8}).show(ui,|ui|{ui.vertical(|ui|{ui.set_width(size.x-268.);
                    egui::ScrollArea::vertical().id_salt(("server-settings-body",&self.server_page)).max_height(size.y-28.).auto_shrink([false,false]).show(ui,|ui|{ui.set_max_width((size.x-280.).min(720.));self.server_body(ui);ui.add_space(24.);});
                });});
            });
        });if close{self.server_settings=false;}
    }
    pub(in crate::ui) fn load_server_page(&mut self){
        let guild=self.server.id.clone();let page=self.server_page.clone();let key=format!("server:{guild}:{page}");
        let suffix=match page.as_str(){"Overview"|"Community"|"Boost Status"=>{self.request_feature(&format!("guild:{guild}"),format!("/guilds/{guild}?with_counts=true"));return;},"Roles"=>{self.load_roles();return;},"Members"=>{self.refresh_members();return;},"Channels"=>{self.send_command(Command::Channels(guild));return;},"Emoji"=>"emojis","Stickers"=>"stickers","Soundboard"=>"soundboard-sounds","Invites"=>"invites","Bans"=>"bans?limit=100","Audit Log"=>"audit-logs?limit=50","Integrations"=>"integrations","Webhooks"=>"webhooks","AutoMod"=>"auto-moderation/rules","Onboarding"=>"onboarding","Welcome Screen"=>"welcome-screen","Server Widget"=>"widget","Server Template"=>"templates","Vanity URL"=>"vanity-url","Notifications"=>{self.request_feature(&key,format!("/users/@me/guilds/{guild}/settings"));return;},_=>return};
        self.request_feature(&key,format!("/guilds/{guild}/{suffix}"));
    }
    fn server_body(&mut self,ui:&mut egui::Ui){
        let page=self.server_page.clone();let guild=self.server.id.clone();let actor=self.user.as_ref().map(|u|u.id.clone()).unwrap_or_default();let manage=self.server.can(&actor,5);let key=format!("server:{guild}:{page}");heading(ui,&page,crate::settings_layout::description(&page));
        crate::settings_layout::card(ui,|ui|{self.feature_status(ui,&format!("guild:{guild}"));self.feature_status(ui,&key);
        match page.as_str(){
            "Overview"|"Community"=>{
                if self.server_edit.is_object(){ui.add_enabled_ui(manage||self.preview,|ui|{
                    sl::section(ui,"Server Profile");ui.add_space(4.);
                    text(ui,&mut self.server_edit,"name","Server name",false);text(ui,&mut self.server_edit,"description","Description",true);
                    sl::label(ui,"Server icon");if ui.button("Change server icon…").clicked(){if let Some(path)=rfd::FileDialog::new().add_filter("Server icon",&["png","jpg","gif","webp"]).pick_file(){match avatar_data(&path){Ok(data)=>self.server_edit["icon"]=json!(data),Err(error)=>self.error=Some(error)}}}
                    ui.add_space(10.);language_picker(ui,&mut self.server_edit,"preferred_locale");
                    sl::divider(ui);sl::section(ui,"Safety & Defaults");ui.add_space(4.);
                    choice(ui,&mut self.server_edit,"verification_level","Verification level",&[(0,"None"),(1,"Low · verified email"),(2,"Medium · account age"),(3,"High · membership age"),(4,"Highest · verified phone")]);
                    choice(ui,&mut self.server_edit,"default_message_notifications","Default notifications",&[(0,"All messages"),(1,"Only mentions")]);choice(ui,&mut self.server_edit,"explicit_content_filter","Sensitive content filtering",&[(0,"Disabled"),(1,"Members without roles"),(2,"All members")]);
                    sl::divider(ui);sl::section(ui,"Channels");ui.add_space(4.);
                    choice(ui,&mut self.server_edit,"afk_timeout","Move inactive members after",&[(60,"1 minute"),(300,"5 minutes"),(900,"15 minutes"),(1800,"30 minutes"),(3600,"1 hour")]);
                    for(field,label)in[("afk_channel_id","AFK voice channel"),("system_channel_id","System messages channel"),("rules_channel_id","Rules channel"),("public_updates_channel_id","Community updates channel"),("safety_alerts_channel_id","Safety alerts channel")]{channel_choice(ui,&mut self.server_edit,field,label,&self.channels);}
                    sl::divider(ui);sl::section(ui,"System Messages");ui.add_space(4.);
                    let mut flags=self.server_edit["system_channel_flags"].as_u64().unwrap_or(0);for(bit,label,description)in[(0,"Welcome Messages","Send a random welcome message when someone joins."),(1,"Boost Messages","Send a message when someone boosts this server."),(2,"Server Setup Tips","Send helpful tips for setting up the server."),(3,"Sticker Reply Button","Prompt members to reply to welcome messages with a sticker."),(4,"Role Subscription Purchases","Send a message when someone buys a role subscription."),(5,"Role Subscription Sticker Replies","Prompt members to reply to role subscription messages.")]{let mut send=flags&(1<<bit)==0;if sl::toggle_row(ui,label,description,&mut send){if send{flags&=!(1<<bit);}else{flags|=1<<bit;}}}self.server_edit["system_channel_flags"]=json!(flags);
                    toggle_desc(ui,&mut self.server_edit,"premium_progress_bar_enabled","Boost Progress Bar","Show the server's boost progress under its name.");
                    ui.add_space(4.);if sl::primary(ui,"Save server changes",!self.feature_pending.contains("save-server")).clicked(){let mut body=delta(&self.server.metadata,&self.server_edit);if let Some(obj)=body.as_object_mut(){obj.retain(|k,_|["name","description","preferred_locale","verification_level","default_message_notifications","explicit_content_filter","afk_timeout","afk_channel_id","system_channel_id","system_channel_flags","rules_channel_id","public_updates_channel_id","safety_alerts_channel_id","premium_progress_bar_enabled","icon"].contains(&k.as_str()));}self.mutate("save-server",Method::PATCH,format!("/guilds/{guild}"),Some(body));}
                });if !manage&&!self.preview{ui.weak("Manage Server permission is required to edit these settings.");}self.feature_status(ui,"save-server");sl::divider(ui);ui.collapsing("Server features",|ui|{if let Some(features)=self.server.metadata["features"].as_array(){for feature in features.iter().filter_map(Value::as_str){ui.label(friendly_name(feature));}}});if page=="Community"{ui.weak("Enabling Community and completing Discord's eligibility/onboarding checks still require Discord's own setup flow.");}}
            }
            "Roles"=>self.roles_editor(ui,&actor),
            "Members"=>{
                ui.add(egui::TextEdit::singleline(&mut self.member_search).hint_text("Search members").desired_width(f32::INFINITY).margin(egui::Margin::symmetric(10,8)));ui.weak(format!("{} loaded / {} reported · bounded to 1,000",self.server.members.len(),self.server.metadata["approximate_member_count"].as_u64().or_else(||self.server.metadata["member_count"].as_u64()).unwrap_or(self.server.members.len()as u64)));
                let mut members:Vec<_>=self.server.members.values().filter(|m|m.name().to_lowercase().contains(&self.member_search.to_lowercase())).cloned().collect();members.sort_by_key(|m|m.name().to_lowercase());for member in members{let response=egui::Frame::NONE.fill(Color32::from_gray(30)).corner_radius(10).inner_margin(10).show(ui,|ui|{ui.horizontal(|ui|{self.user_avatar(ui,&member.user,member.avatar.as_deref(),34.);ui.vertical(|ui|{ui.strong(member.name());if member.mute{ui.weak("Server muted");}if member.deaf{ui.weak("Server deafened");}ui.horizontal_wrapped(|ui|{for role in self.server.roles.iter().filter(|r|member.roles.contains(&r.id)){let c=role.rgb();ui.colored_label(if c==0{TEXT}else{Color32::from_rgb((c>>16)as u8,(c>>8)as u8,c as u8)},&role.name);}});});});}).response.interact(egui::Sense::click());response.context_menu(|ui|self.user_menu(ui,&member.user));}
                if self.server.has_more&&self.server.members.len()<community::MEMBER_LIMIT&&ui.button("Load next 100 members").clicked(){let after=self.server.cursor.clone().unwrap_or_default();self.request_feature(&format!("members:{guild}"),format!("/guilds/{guild}/members?limit=100&after={after}"));}self.feature_status(ui,&format!("members:{guild}"));
            }
            "Channels"=>self.channels_editor(ui,&actor),
            "Boost Status"=>{let tier=self.server.metadata["premium_tier"].as_u64().unwrap_or(0);let boosts=self.server.metadata["premium_subscription_count"].as_u64().unwrap_or(0);ui.horizontal(|ui|{ui.spacing_mut().item_spacing.x=12.;let w=((ui.available_width()-12.)/2.).max(140.);for(value,caption)in[(format!("Level {tier}"),"Current boost level"),(boosts.to_string(),"Active boosts")]{egui::Frame::NONE.fill(Color32::from_gray(30)).corner_radius(12).inner_margin(16).show(ui,|ui|{ui.set_width(w-32.);ui.label(RichText::new(value).size(24.).strong().color(TEXT));ui.label(RichText::new(caption).color(MUTED));});}});ui.add_space(10.);ui.hyperlink_to("Manage server boosts ↗","https://discord.com/channels/@me");},
            "Notifications"=>{
                let mut data=self.features.get(&key).cloned().unwrap_or_else(||json!({}));toggle_desc(ui,&mut data,"muted","Mute Server","Stop all notifications from this server.");choice(ui,&mut data,"message_notifications","Notify me for",&[(0,"All messages"),(1,"Only @mentions"),(2,"Nothing"),(3,"Use server default")]);toggle_desc(ui,&mut data,"suppress_everyone","Suppress @everyone and @here","Ignore mass mentions in this server.");toggle_desc(ui,&mut data,"suppress_roles","Suppress All Role @mentions","Ignore mentions of roles you have.");toggle_desc(ui,&mut data,"mobile_push","Mobile Push Notifications","Send notifications to your phone.");toggle_desc(ui,&mut data,"hide_muted_channels","Hide Muted Channels","Hide channels you have muted from the channel list.");self.features.insert(key.clone(),data.clone());ui.add_space(10.);if sl::primary(ui,"Save notification settings",true).clicked(){let mut body=data;if let Some(o)=body.as_object_mut(){o.retain(|k,_|["muted","message_notifications","suppress_everyone","suppress_roles","mobile_push","hide_muted_channels"].contains(&k.as_str()));}self.mutate("save-notifications",Method::PATCH,format!("/users/@me/guilds/{guild}/settings"),Some(body));}self.feature_status(ui,"save-notifications");
            }
            "Server Widget"=>{let mut data=self.features.get(&key).cloned().unwrap_or_else(||json!({}));ui.add_enabled_ui(manage,|ui|{toggle_desc(ui,&mut data,"enabled","Enable Server Widget","Let websites show who is online and an invite button.");channel_choice(ui,&mut data,"channel_id","Invite channel",&self.channels);ui.add_space(6.);if sl::primary(ui,"Save widget",true).clicked(){self.mutate("server-write",Method::PATCH,format!("/guilds/{guild}/widget"),Some(json!({"enabled":data["enabled"],"channel_id":data["channel_id"]})));}});self.features.insert(key,data);self.feature_status(ui,"server-write");},
            "Vanity URL"=>{let mut data=self.features.get(&key).cloned().unwrap_or_else(||json!({}));ui.add_enabled_ui(manage,|ui|{text(ui,&mut data,"code","Vanity invite code",false);if sl::primary(ui,"Save vanity URL",true).clicked(){self.mutate("server-write",Method::PATCH,format!("/guilds/{guild}/vanity-url"),Some(json!({"code":data["code"]})));}});self.features.insert(key,data);ui.weak("Requires Discord's server eligibility for a custom invite link.");self.feature_status(ui,"server-write");},
            "Onboarding"|"Welcome Screen"|"AutoMod"=>{
                if let Some(data)=self.features.get(&key).cloned(){json_cards(ui,&data);ui.collapsing("Configuration details",|ui|{ui.add(egui::Label::new(serde_json::to_string_pretty(&data).unwrap_or_default()).wrap().selectable(true));});ui.weak("Advanced onboarding, AutoMod rule creation and welcome-screen editing are not implemented in this build.");}ui.hyperlink_to("Open server in Discord",format!("https://discord.com/channels/{guild}"));
            }
            _=>self.server_resource_list(ui,&key,&page,&actor),
        }
        sl::divider(ui);if ui.button("⟳  Refresh this section").clicked(){self.load_server_page();}
        });
    }
    fn roles_editor(&mut self,ui:&mut egui::Ui,actor:&str){
        let guild=self.server.id.clone();if self.server.can(actor,28)&&ui.button("Create role").clicked(){self.mutate("create-role",Method::POST,format!("/guilds/{guild}/roles"),Some(json!({"name":"New role","permissions":"0"})));}self.feature_status(ui,"create-role");
        let mut roles=self.server.roles.clone();roles.sort_by_key(|r|std::cmp::Reverse(r.position));ui.add_space(6.);for role in roles{let color=role.rgb();let dot=if color==0{Color32::from_gray(150)}else{Color32::from_rgb((color>>16)as u8,(color>>8)as u8,color as u8)};let response=sl::list_row(ui,&role.name,if role.managed{"Managed by an integration"}else{""},Some(dot),self.role_edit.as_ref().is_some_and(|r|r.id==role.id));if response.clicked(){self.role_edit=Some(role);}}
        if let Some(mut role)=self.role_edit.clone(){sl::divider(ui);let editable=self.server.can_edit_role(actor,&role);ui.add_enabled_ui(editable||self.preview,|ui|{sl::section(ui,"Edit Role");ui.add_space(4.);sl::label(ui,"Role name");ui.add(egui::TextEdit::singleline(&mut role.name).desired_width(f32::INFINITY).margin(egui::Margin::symmetric(10,8)));ui.add_space(10.);sl::label(ui,"Role color");let mut rgb=[(role.rgb()>>16)as u8,(role.rgb()>>8)as u8,role.rgb()as u8];ui.horizontal(|ui|{ui.spacing_mut().interact_size=Vec2::new(52.,30.);if ui.color_edit_button_srgb(&mut rgb).changed(){role.color=((rgb[0]as u32)<<16)|((rgb[1]as u32)<<8)|rgb[2]as u32;role.colors=None;}});ui.add_space(12.);sl::toggle_row(ui,"Display Separately","Show members with this role separately in the member list.",&mut role.hoist);sl::toggle_row(ui,"Allow Anyone to @mention","Members can mention this role to notify everyone who has it.",&mut role.mentionable);ui.add_space(6.);sl::section(ui,"Permissions");ui.add_space(4.);let mut bits=role.bits();for (bit,label) in PERMISSIONS{let flag=1u64<<bit;let mut enabled=bits&flag!=0;let allowed=self.server.permissions(actor)&flag!=0||enabled;ui.push_id(bit,|ui|{ui.add_enabled_ui(allowed,|ui|{if sl::toggle_row(ui,&title_case(label),"",&mut enabled){if enabled{bits|=flag;}else{bits&=!flag;}}});});}role.permissions=bits.to_string();ui.add_space(8.);if sl::primary(ui,"Save role",!self.feature_pending.contains("save-role")).clicked(){self.mutate("save-role",Method::PATCH,format!("/guilds/{guild}/roles/{}",role.id),Some(json!({"name":role.name,"permissions":role.permissions,"color":role.color,"hoist":role.hoist,"mentionable":role.mentionable})));}
            if role.id!=guild&&ui.button(RichText::new("Delete role").color(Color32::LIGHT_RED)).clicked(){self.confirm=Some((format!("Permanently delete role {}?",role.name),Command::Request{key:"save-role".into(),method:Method::DELETE,route:format!("/guilds/{guild}/roles/{}",role.id),body:None}));}
        });if !editable&&!self.preview{ui.weak("This role is managed by an integration or is at/above your highest role. Editing is unavailable.");}self.role_edit=Some(role);}self.feature_status(ui,"save-role");
    }
    fn channels_editor(&mut self,ui:&mut egui::Ui,actor:&str){
        let manage=self.server.can(actor,4);let guild=self.server.id.clone();let mut selected=None;
        for channel in self.channels.clone(){if sl::list_row(ui,&format!("{} {}",if channel.kind==2{"🔊"}else if channel.kind==4{"▾"}else{"#"},channel.label()),if channel.kind==4{"Category"}else if channel.kind==2{"Voice channel"}else{""},None,self.features.get("channel-edit").is_some_and(|v|v["id"].as_str()==Some(&channel.id))).clicked(){selected=Some(channel);}}
        if let Some(channel)=selected{self.features.insert("channel-edit".into(),json!({"id":channel.id,"name":channel.name,"topic":channel.topic,"type":channel.kind,"rate_limit_per_user":channel.rate_limit_per_user,"bitrate":channel.bitrate.unwrap_or(64000),"user_limit":channel.user_limit.unwrap_or(0),"nsfw":channel.nsfw}));}
        if let Some(mut edit)=self.features.get("channel-edit").cloned(){sl::divider(ui);ui.add_enabled_ui(manage||self.preview,|ui|{text(ui,&mut edit,"name","Channel name",false);text(ui,&mut edit,"topic","Topic",true);toggle_desc(ui,&mut edit,"nsfw","Age-Restricted Channel","Members must confirm they are over the legal age to view it.");if edit["type"].as_u64()==Some(2){number(ui,&mut edit,"bitrate","Bitrate",8000..=384000);number(ui,&mut edit,"user_limit","User limit (0 = unlimited)",0..=99);}else{number(ui,&mut edit,"rate_limit_per_user","Slowmode seconds",0..=21600);}if sl::primary(ui,"Save channel",true).clicked(){if let Some(id)=edit["id"].as_str().map(str::to_owned){let mut body=edit.clone();body.as_object_mut().unwrap().remove("id");body.as_object_mut().unwrap().remove("type");self.mutate("save-channel",Method::PATCH,format!("/channels/{id}"),Some(body));}}});self.features.insert("channel-edit".into(),edit);}
        if manage {sl::divider(ui);let mut create=self.features.get("new-channel").cloned().unwrap_or_else(||json!({"name":"new-channel","type":0}));text(ui,&mut create,"name","New channel name",false);choice(ui,&mut create,"type","Channel type",&[(0,"Text"),(2,"Voice"),(4,"Category")]);if sl::primary(ui,"Create channel",true).clicked(){self.mutate("create-channel",Method::POST,format!("/guilds/{guild}/channels"),Some(create.clone()));}self.features.insert("new-channel".into(),create);}self.feature_status(ui,"save-channel");self.feature_status(ui,"create-channel");
    }
    fn server_resource_list(&mut self,ui:&mut egui::Ui,key:&str,page:&str,actor:&str){
        let guild=self.server.id.clone();let data=self.features.get(key).cloned().unwrap_or(Value::Null);let items=data.as_array().or_else(||data["items"].as_array()).or_else(||data["audit_log_entries"].as_array());
        if let Some(items)=items{if items.is_empty(){ui.weak("No entries.");}for item in items.iter().take(200){egui::Frame::NONE.fill(Color32::from_gray(30)).corner_radius(10).inner_margin(14).show(ui,|ui|{let name=item["name"].as_str().or_else(||item["user"]["global_name"].as_str()).or_else(||item["user"]["username"].as_str()).or_else(||item["code"].as_str()).unwrap_or("Entry");ui.strong(name);if let Some(reason)=item["reason"].as_str(){ui.label(reason);}if let Some(action)=item["action_type"].as_u64(){ui.weak(audit_action(action));if let Some(user)=item["user_id"].as_str().and_then(|id|self.server.members.get(id)){ui.label(format!("By {}",user.name()));}if self.prefs.developer{ui.collapsing("Technical details",|ui|{ui.label(format!("Action {action}"));ui.label(format!("Target: {}",item["target_id"].as_str().unwrap_or("Unknown")));});}}
            if page=="Emoji"{if let(Some(id),Some(animated))=(item["id"].as_str(),item["animated"].as_bool()){if let Some(url)=crate::media_picker::emoji_url(id,animated){crate::message_media::picture(ui,&mut self.images,&url,Some(64),Some(64),false);}}}
            if page=="Invites"{if let Some(code)=item["code"].as_str(){ui.hyperlink_to("Copy / open invitation",format!("https://discord.gg/{code}"));}}
            if page=="Bans"&&self.server.can(actor,2){if let Some(id)=item["user"]["id"].as_str(){if ui.button("Revoke ban").clicked(){self.confirm=Some((format!("Unban {name}?"),Command::Request{key:"server-write".into(),method:Method::DELETE,route:format!("/guilds/{guild}/bans/{id}"),body:None}));}}}
            if matches!(page,"Emoji"|"Stickers")&&self.server.can(actor,30){if let Some(id)=item["id"].as_str(){if ui.button("Delete").clicked(){let resource=if page=="Emoji"{"emojis"}else{"stickers"};self.confirm=Some((format!("Delete {name} from this server?"),Command::Request{key:"server-write".into(),method:Method::DELETE,route:format!("/guilds/{guild}/{resource}/{id}"),body:None}));}}}
        });ui.add_space(8.);}}else if !data.is_null(){json_cards(ui,&data);}else if !self.feature_pending.contains(key){ui.weak("Choose Refresh this section to load data. Discord may restrict this section based on your permissions.");}
        if page=="Emoji"&&self.server.can(actor,43){sl::divider(ui);let mut upload=self.features.get("new-emoji").cloned().unwrap_or_else(||json!({"name":"new_emoji"}));text(ui,&mut upload,"name","New emoji name",false);if ui.button("Choose image and upload emoji…").clicked(){if let Some(path)=rfd::FileDialog::new().add_filter("Emoji image",&["png","gif","webp","jpg"]).pick_file(){match avatar_data(&path){Ok(image)=>{upload["image"]=json!(image);self.mutate("server-write",Method::POST,format!("/guilds/{guild}/emojis"),Some(upload.clone()));},Err(error)=>self.error=Some(error)}}}upload.as_object_mut().unwrap().remove("image");self.features.insert("new-emoji".into(),upload);}
        self.feature_status(ui,"server-write");
    }
}
fn title_case(s:&str)->String{s.split(' ').map(|w|{let mut c=w.chars();c.next().map(|f|f.to_uppercase().collect::<String>()+c.as_str()).unwrap_or_default()}).collect::<Vec<_>>().join(" ").replace("Tts","TTS").replace("Vad","Voice Activity")}
fn channel_choice(ui:&mut egui::Ui,value:&mut Value,key:&str,label:&str,channels:&[Channel]){let mut selected=value[key].as_str().map(str::to_owned);sl::label(ui,label);egui::ComboBox::from_id_salt(key).width(ui.available_width().min(380.)).selected_text(selected.as_ref().and_then(|id|channels.iter().find(|c|&c.id==id)).map(Channel::label).unwrap_or("None".into())).show_ui(ui,|ui|{ui.selectable_value(&mut selected,None,"None");for c in channels{ui.selectable_value(&mut selected,Some(c.id.clone()),c.label());}});value[key]=selected.map(Value::String).unwrap_or(Value::Null);ui.add_space(10.);}
const PERMISSIONS:&[(u8,&str)]=&[(0,"create instant invite"),(1,"kick members"),(2,"ban members"),(3,"administrator"),(4,"manage channels"),(5,"manage guild"),(6,"add reactions"),(7,"view audit log"),(8,"priority speaker"),(9,"stream"),(10,"view channel"),(11,"send messages"),(12,"send tts messages"),(13,"manage messages"),(14,"embed links"),(15,"attach files"),(16,"read message history"),(17,"mention everyone"),(18,"use external emojis"),(19,"view guild insights"),(20,"connect"),(21,"speak"),(22,"mute members"),(23,"deafen members"),(24,"move members"),(25,"use vad"),(26,"change nickname"),(27,"manage nicknames"),(28,"manage roles"),(29,"manage webhooks"),(30,"manage guild expressions"),(31,"use application commands"),(32,"request to speak"),(33,"manage events"),(34,"manage threads"),(35,"create public threads"),(36,"create private threads"),(37,"use external stickers"),(38,"send messages in threads"),(39,"use embedded activities"),(40,"moderate members"),(41,"view creator monetization analytics"),(42,"use soundboard"),(43,"create guild expressions"),(44,"create events"),(45,"use external sounds"),(46,"send voice messages"),(48,"set voice channel status"),(49,"send polls"),(50,"use external apps"),(51,"pin messages"),(52,"bypass slowmode")];
